window.AUTH=window.AUTH||{};window.AUTH["24-699"]={"d":"24-699","id":"2025/24-699","n":"Exxon Mobil Corp. v. Corporación Cimex, S.A. (Cuba)","briefs":[{"k":"petitioner","label":"Brief of petitioner Exxon Mobil Corporation","date":"2025-11-28","url":"https://www.supremecourt.gov/DocketPDF/24/24-699/385940/20251128123944417_24-699_Merits%20Brief_to%20e-file.pdf","side":"pet","n":34},{"k":"united-states","label":"Brief amicus curiae of United States in support of petitioner","date":"2025-12-05","url":"https://www.supremecourt.gov/DocketPDF/24/24-699/386574/20251205145704706_24-699tsacUnitedStates.pdf","side":"pet","n":87},{"k":"respondent","label":"Brief of respondents Corporación CIMEX, S.A. (Cuba), et al.","date":"2026-01-09","url":"https://www.supremecourt.gov/DocketPDF/24/24-699/391287/20260109133437554_24-699%20Respondents%20Brief.pdf","side":"res","n":155},{"k":"reply","label":"Reply of petitioner Exxon Mobil Corporation","date":"2026-02-04","url":"https://www.supremecourt.gov/DocketPDF/24/24-699/395440/20260204122814993_Exxon%20-%20Merits%20Reply%202.4.26%20-%20TO%20E-FILE.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/609us1r56_3e04.pdf","tr":true,"items":[{"t":"case","label":"Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"sum":"A sharply divided court held in a 5-4 decision that Congress may not use its Article I powers to abrogate the states' sovereign immunity. Both the terms and history of the eleventh amendment suggest that States are immune from suits in their own courts.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Argentine Republic v. Amerada Hess Shipping Corp.","cite":"488 U.S. 428","y":1989,"id":"1988/87-1372","sc":1,"op":2,"sum":"The FSIA provides the sole basis for obtaining jurisdiction over a foreign state in United States courts, and the District Court correctly dismissed the action because the FSIA did not authorize jurisdiction over petitioner under the facts of this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 39, 40","1":"17, 28","2":"4, 26, 44, 45"}},{"t":"case","label":"Atascadero State Hospital v. Scanlon","cite":"473 U.S. 234","y":1985,"id":"1984/84-351","sc":1,"sum":"Respondent's action is proscribed by the Eleventh Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Atlantic Richfield Co. v. Christian","cite":"590 U.S. 1","y":2020,"id":"2019/17-1498","sc":1,"sum":"The Court held that the landowners in this case were potentially responsible parties under the Comprehensive Environmental Response, Compensation, and Liability Act (CERCLA) and thus need the Environmental Protection Agency’s approval to take remedial action.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Banco Nacional de Cuba v. Sabbatino","cite":"376 U.S. 398","y":1964,"id":"1963/16","sc":1,"sum":"The Supreme Court held that it will not decide the validity of a decree by a foreign government absent a treaty or other agreement. It did not matter that the taking violated customary international law. The majority noted that a judicial decision on this issue without a treaty would strain U.S.-Cuba relations.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"CC/Devas (Mauritius) Ltd. v. Antrix Corp.","cite":"605 U.S. 223","y":2025,"id":"2024/23-1201","sc":1,"op":1,"sum":"To exercise personal jurisdiction over a foreign state, the Foreign Sovereign Immunities Act does not require proof of “minimum contacts” over and above the contacts already required by the Act’s enumerated exceptions to foreign sovereign immunity.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"30, 42, 47","1":"5, 23, 27","2":"5, 40, 43","3":"15"}},{"t":"case","label":"Connecticut Bank of Commerce v. Republic of Congo","cite":"309 F.3d 240","y":2002,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/309/240/","by":{"0":"48-49"}},{"t":"case","label":"Dellmuth v. Muth","cite":"491 U.S. 223","y":1989,"id":"1988/87-1855","sc":1,"by":{"0":"35, 42","3":"3, 4"}},{"t":"case","label":"Department of Agriculture Rural Development Rural Housing Service v. Kirtz","cite":"601 U.S. 42","y":2024,"id":"2023/22-846","sc":1,"op":13,"sum":"A consumer may sue a federal agency under 15 U. S. C. §§1681n and 1681o for defying the terms of the Fair Credit Reporting Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"3, 4, 15, 21-24, 26, 35-37, 46, 50","1":"13-15, 19, 21, 30-33","2":"10-12, 15-17, 27, 30, 34, 50","3":"2, 4, 6, 9, 10, 18, 21"}},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"sum":"The Court held that criminals who had committed drug crimes before the passage of the Fair Sentencing Act of 2010 but were sentenced after its passage were entitled to the sentencing provisions laid out in the Act.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Financial Oversight & Mgmt. Bd. for Puerto Rico v. Centro de Periodismo Investigativo, Inc.","cite":"598 U.S. 339","y":2023,"id":"2022/22-96","sc":1,"op":7,"ar":1,"sum":"Nothing in the Puerto Rico Oversight, Management, and Economic Stability Act—including its jurisdictional provision, 48 U. S. C. §2126(a)—categorically abrogates any sovereign immunity the Financial Oversight and Management Board for Puerto Rico enjoys from legal claims.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23","1":"17, 19, 21","2":"16, 34","3":"4, 9"}},{"t":"case","label":"(V) Fitzpatrick v. Butler","cite":"427 U.S. 445","y":1976,"id":"1975/75-251","sc":1,"sum":"Present and retired male employees of the State of Connecticut (petitioners in No. 75-251) brought this class action alleging, inter alia, that certain provisions of the State's statutory retirement benefit plan discriminated against them because of their sex, in violation of Title VII of the Civil Rights Act of 1964, which, as amended, extends coverage to the States as employers. The District Court ruled in their …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Fletcher v. Peck","cite":"10 U.S. 87","y":1810,"id":"1789-1850/10us87","sc":1,"op":1,"sum":"The Court held that a contract is still binding and enforceable, even if secured illegally.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Fuld v. Palestine Liberation Org.","cite":"606 U.S. 1","y":2025,"id":"2024/24-20","sc":1,"sum":"The Promoting Security and Justice for Victims of Terrorism Act’s personal jurisdiction provision does not violate the Fifth Amendment’s Due Process Clause because the statute reasonably ties the assertion of jurisdiction over the PLO and PA to conduct involving the United States and implicating sensitive foreign policy matters within the prerogative of the political branches.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"47","1":"27","2":"41"}},{"t":"case","label":"Guidry v. Sheet Metal Workers Nat. Pension Fund","cite":"493 U.S. 365","y":1990,"id":"1989/88-1105","sc":1,"sum":"The constructive trust violates ERISA's prohibition on assignment or alienation of pension benefits.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39","1":"24"}},{"t":"case","label":"Kimel v. Florida Bd. of Regents","cite":"528 U.S. 62","y":2000,"id":"1999/98-791","sc":1,"op":2,"ar":4,"sum":"The Court held that the ADEA contains a clear statement of Congress' intent to abrogate the states' immunity, but that the abrogation exceeds Congress' authority under the Fourteenth Amendment. \"States may discriminate on the basis of age without offending the Fourteenth Amendment if the age classification in question is rationally related to a legitimate state interest,\" wrote Justice O'Connor for the Court.","sumSrc":"Oyez","by":{"0":"22","3":"4, 8, 9"}},{"t":"case","label":"Marcello v. Bonds","cite":"349 U.S. 302","y":1955,"id":"scdb/1954-086","sc":1,"sum":"After a hearing pursuant to § 242 (b) of the Immigration and Nationality Act of 1952, petitioner, an alien who had been convicted in 1938 of violation of the Marihuana Tax Act, was ordered deported. Section 241 (a) (11) of the 1952 Act makes such conviction at any time ground for deportation, and § 241 (d) provides that the deportation prdvisions of § 241 (a) shall apply even though the facts giving rise to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"0":"39","2":"20"}},{"t":"case","label":"Nevada Dep’t of Human Resources v. Hibbs","cite":"538 U.S. 721","y":2003,"id":"2002/01-1368","sc":1,"op":1,"sum":"The Court held that State employees may recover money damages in federal court in the event of the State's failure to comply with the FMLA's family-care provision.","sumSrc":"Oyez","by":{"0":"22","3":"10"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"0":"39, 41","1":"28"}},{"t":"case","label":"Permanent Mission of India to the United Nations v. New York","cite":"551 U.S. 193","y":2007,"id":"2006/06-134","sc":1,"sum":"The Court held 7-2 that the \"immovable property\" exception to sovereign immunity in the FSIA covers disputes over tax liens on the property as well as disputes over ownership and possession. The opinion by Justice Clarence Thomas ruled that a tax lien, by both its dictionary definition and its practical effect, is an interest or right in property.","sumSrc":"Oyez","by":{"0":"39","2":"42"}},{"t":"case","label":"Republic of Austria v. Altmann","cite":"541 U.S. 677","y":2004,"id":"2003/03-13","sc":1,"op":3,"sum":"In a 6-to-3 decision written by Justice John Paul Stevens, the Court ruled that, while the Foreign Sovereign Immunities Act of 1976 does not explicitly state that it should be applied to actions that took place before its passage, there are strong indications in the text of the statute that Congress intended it to apply retroactively.","sumSrc":"Oyez","by":{"0":"39, 41","1":"12, 28","2":"49"}},{"t":"case","label":"Turkiye Halk Bankasi A.S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"op":7,"sum":"The District Court has jurisdiction of this criminal prosecution under 18 U. S. C. §3231, and the Foreign Sovereign Immunities Act’s comprehensive scheme governing claims of immunity in civil actions against foreign states and their instrumentalities does not cover criminal cases.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"29, 40, 41","1":"5, 28","2":"29, 39, 44, 47","3":"7"}},{"t":"case","label":"United States v. Clarke","cite":"33 U.S. 436","y":1834,"id":"scdb/1834-045","sc":1,"sum":"The case was argued by Mr Call, for the United-States; and by Mr Berrien and Mr Wilde, for the appellee.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Verlinden B.V. v. Central Bank of Nigeria","cite":"461 U.S. 480","y":1983,"id":"1982/81-920","sc":1,"op":1,"sum":"The Supreme Court held that the FSIA does not violate Article III. The FSIA was a valid exercise of Congress’ power to regulate foreign commerce. On remand, the court of appeals should consider whether Central Bank is entitled to sovereign immunity.","sumSrc":"Oyez","by":{"0":"20, 34","1":"5","2":"26, 40, 47, 49"}},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"30"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"usc","label":"22 U.S.C. § 6021","url":"https://www.law.cornell.edu/uscode/text/22/6021","stext":{"head":"§6021. Findings","paras":[[0,"The Congress makes the following findings:"],[1,"(1) The economy of Cuba has experienced a decline of at least 60 percent in the last 5 years as a result of—"],[2,"(A) the end of its subsidization by the former Soviet Union of between 5 billion and 6 billion dollars annually;"],[2,"(B) 36 years of communist tyranny and economic mismanagement by the Castro government;"],[2,"(C) the extreme decline in trade between Cuba and the countries of the former Soviet bloc; and"],[2,"(D) the stated policy of the Russian Government and the countries of the former Soviet bloc to conduct economic relations with Cuba on strictly commercial terms."],[1,"(2) At the same time, the welfare and health of the Cuban people have substantially deteriorated as a result of this economic decline and the refusal of the Castro regime to permit free and fair democratic elections in Cuba."],[1,"(3) The Castro regime has made it abundantly clear that it will not engage in any substantive political reforms that would lead to democracy, a market economy, or an economic recovery."],[1,"(4) The repression of the Cuban people, including a ban on free and fair democratic elections, and continuing violations of fundamental human rights, have isolated the Cuban regime as the only completely nondemocratic government in the Western Hemisphere."],[1,"(5) As long as free elections are not held in Cuba, the economic condition of the country and the welfare of the Cuban people will not improve in any significant way."],[1,"(6) The totalitarian nature of the Castro regime has deprived the Cuban people of any peaceful means to improve their condition and has led thousands of Cuban citizens to risk or lose their lives in dangerous attempts to escape from Cuba to freedom."],[1,"(7) Radio Marti and Television Marti have both been effective vehicles for providing the people of Cuba with news and information and have helped to bolster the morale of the people of Cuba living under tyranny."],[1,"(8) The consistent policy of the United States towards Cuba since the beginning of the Castro regime, carried out by both Democratic and Republican administrations, has sought to keep faith with the people of Cuba, and has been effective in sanctioning the totalitarian Castro regime."],[1,"(9) The United States has shown a deep commitment, and considers it a moral obligation, to promote and protect human rights and fundamental freedoms as expressed in the Charter of the United Nations and in the Universal Declaration of Human Rights."],[1,"(10) The Congress has historically and consistently manifested its solidarity and the solidarity of the American people with the democratic aspirations of the Cuban people."],[1,"(11) The Cuban Democracy Act of 1992 [22 U.S.C. 6001 et seq.] calls upon the President to encourage the governments of countries that conduct trade with Cuba to restrict their trade and credit relations with Cuba in a manner consistent with the purposes of that Act."],[1,"(12) Amendments to the Foreign Assistance Act of 1961 [22 U.S.C. 2151 et seq.] made by the FREEDOM Support Act require that the President, in providing economic assistance to Russia and the emerging Eurasian democracies, take into account the extent to which they are acting to \"terminate support for the communist regime in Cuba, including removal of troops, closing military facilities, and ceasing trade subsidies and economic, nuclear, and other assistance\"."],[1,"(13) The Cuban Government engages in the illegal international narcotics trade and harbors fugitives from justice in the United States."],[1,"(14) The Castro government threatens international peace and security by engaging in acts of armed subversion and terrorism such as the training and supplying of groups dedicated to international violence."],[1,"(15) The Castro government has utilized from its inception and continues to utilize torture in various forms (including by psychiatry), as well as execution, exile, confiscation, political imprisonment, and other forms of terror and repression, as means of retaining power."],[1,"(16) Fidel Castro has defined democratic pluralism as \"pluralistic garbage\" and continues to make clear that he has no intention of tolerating the democratization of Cuban society."],[1,"(17) The Castro government holds innocent Cubans hostage in Cuba by no fault of the hostages themselves solely because relatives have escaped the country."],[1,"(18) Although a signatory state to the 1928 Inter-American Convention on Asylum and the International Covenant on Civil and Political Rights (which protects the right to leave one's own country), Cuba nevertheless surrounds embassies in its capital by armed forces to thwart the right of its citizens to seek asylum and systematically denies that right to the Cuban people, punishing them by imprisonment for seeking to leave the country and killing them for attempting to do so (as demonstrated in the case of the confirmed murder of over 40 men, women, and children who were seeking to leave Cuba on July 13, 1994)."],[1,"(19) The Castro government continues to utilize blackmail, such as the immigration crisis with which it threatened the United States in the summer of 1994, and other unacceptable and illegal forms of conduct to influence the actions of sovereign states in the Western Hemisphere in violation of the Charter of the Organization of American States and other international agreements and international law."],[1,"(20) The United Nations Commission on Human Rights has repeatedly reported on the unacceptable human rights situation in Cuba and has taken the extraordinary step of appointing a Special Rapporteur."],[1,"(21) The Cuban Government has consistently refused access to the Special Rapporteur and formally expressed its decision not to \"implement so much as one comma\" of the United Nations Resolutions appointing the Rapporteur."],[1,"(22) The United Nations General Assembly passed Resolution 47–139 on December 18, 1992, Resolution 48–142 on December 20, 1993, and Resolution 49–200 on December 23, 1994, referencing the Special Rapporteur's reports to the United Nations and condemning violations of human rights and fundamental freedoms in Cuba."],[1,"(23) Article 39 of Chapter VII of the United Nations Charter provides that the United Nations Security Council \"shall determine the existence of any threat to the peace, breach of the peace, or act of aggression and shall make recommendations, or decide what measures shall be taken . . ., to maintain or restore international peace and security.\"."],[1,"(24) The United Nations has determined that massive and systematic violations of human rights may constitute a \"threat to peace\" under Article 39 and has imposed sanctions due to such violations of human rights in the cases of Rhodesia, South Africa, Iraq, and the former Yugoslavia."],[1,"(25) In the case of Haiti, a neighbor of Cuba not as close to the United States as Cuba, the United States led an effort to obtain and did obtain a United Nations Security Council embargo and blockade against that country due to the existence of a military dictatorship in power less than 3 years."],[1,"(26) United Nations Security Council Resolution 940 of July 31, 1994, subsequently authorized the use of \"all necessary means\" to restore the \"democratically elected government of Haiti\", and the democratically elected government of Haiti was restored to power on October 15, 1994."],[1,"(27) The Cuban people deserve to be assisted in a decisive manner to end the tyranny that has oppressed them for 36 years, and the continued failure to do so constitutes ethically improper conduct by the international community."],[1,"(28) For the past 36 years, the Cuban Government has posed and continues to pose a national security threat to the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/6021?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6021. Findings","tname":"Foreign Relations and Intercourse","by":{"0":"9","1":"1, 2, 31","2":"6-8, 28, 30","3":"15"}},{"t":"usc","label":"28 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/28/1602","stext":{"head":"§1602. Findings and declaration of purpose","paras":[[0,"The Congress finds that the determination by United States courts of the claims of foreign states to immunity from the jurisdiction of such courts would serve the interests of justice and would protect the rights of both foreign states and litigants in United States courts. Under international law, states are not immune from the jurisdiction of foreign courts insofar as their commercial activities are concerned, and their commercial property may be levied upon for the satisfaction of judgments rendered against them in connection with their commercial activities. Claims of foreign states to immunity should henceforth be decided by courts of the United States and of the States in conformity with the principles set forth in this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1602?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1602. Findings and declaration of purpose","tname":"Judiciary and Judicial Procedure","by":{"0":"13, 29, 38","3":"21"}},{"t":"usc","label":"22 U.S.C. § 1643","url":"https://www.law.cornell.edu/uscode/text/22/1643","stext":{"head":"§1643. Congressional declaration of purpose","paras":[[0,"It is the purpose of this subchapter to provide for the determination of the amount and validity of claims against the Government of Cuba, or the Chinese Communist regime, which have arisen since January 1, 1959, in the case of claims against the Government of Cuba, or since October 1, 1949, in the case of claims against the Chinese Communist regime, out of nationalization, expropriation, intervention, or other takings of, or special measures directed against, property of nationals of the United States, and claims for disability or death of nationals of the United States arising out of violations of international law by the Government of Cuba, or the Chinese Communist regime, in order to obtain information concerning the total amount of such claims against the Government of Cuba, or the Chinese Communist regime, on behalf of nationals of the United States. This subchapter shall not be construed as authorizing an appropriation or as any intention to authorize an appropriation for the purpose of paying such claims."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/1643?type=usc&year=mostrecent&link-type=html"},"head":"§1643. Congressional declaration of purpose","tname":"Foreign Relations and Intercourse","by":{"0":"7","1":"7"}},{"t":"usc","label":"15 U.S.C. § 1681a","url":"https://www.law.cornell.edu/uscode/text/15/1681a","subs":["(b)"],"by":{"0":"15, 23","1":"13"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"5"}},{"t":"usc","label":"29 U.S.C. § 203","url":"https://www.law.cornell.edu/uscode/text/29/203","by":{"0":"22"}},{"t":"rule","label":"Fed. R. Civ. P. 4","url":"https://www.law.cornell.edu/rules/frcp/rule_4","subs":["(k)(1)(C)","(j)(1)"],"by":{"0":"47","1":"25","2":"53"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"578 U.S. 212","y":2016,"id":"2015/14-770","sc":1,"op":2,"sum":"The Court decided that a statute effectively directing a particular result in a single pending case does not violate the separation of powers.","sumSrc":"Oyez","by":{"1":"18, 28, 29"}},{"t":"case","label":"Federal Republic of Germany v. Philipp","cite":"592 U.S. 169","y":2021,"id":"2020/19-351","sc":1,"sum":"The Foreign Sovereign Immunities Act’s expropriation exception, 28 U. S. C. §1605(a)(3), incorporates the domestic takings rule, which recognizes that a foreign sovereign’s taking of its own nationals’ property is not a violation of international law.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"27"}},{"t":"case","label":"Kemp v. United States","cite":"596 U.S. 528","y":2022,"id":"2021/21-5726","sc":1,"sum":"The term “mistake” in Federal Rule of Civil Procedure 60(b)(1) includes a judge’s errors of law; because Kemp’s motion alleged such an error, it was cognizable under Rule 60(b)(1) and untimely under Rule 60(c)’s 1-year limitations period.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"24"}},{"t":"case","label":"Peterson v. Islamic Republic of Iran","cite":"627 F.3d 1117","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/627/1117/","by":{"1":"32"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Reichelderfer v. Quinn","cite":"287 U.S. 315","y":1932,"id":"scdb/1932-029","sc":1,"sum":"(1) The neighboring landowners derived no rights against the Government from the dedication of the park alone, since this constituted only a declaration of Dublic policy by the particular Congress, which was not binding on its successors. P. 318, (2) Assuming that the building of the engine hoise was a diversion of the land from park uses, the change of use wa. within the. legislative power. P. 320. 2z The existence …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Republic of Argentina v. NML Capital, Ltd.","cite":"573 U.S. 134","y":2014,"id":"2013/12-842","sc":1,"op":2,"sum":"The Court held that, under the Foreign Sovereign Immunities Act, property held within the US by foreign nations cannot be attached to civil claims unless certain exceptions are met.","sumSrc":"Oyez","by":{"1":"6, 17, 26, 31, 32","2":"39, 47, 49","3":"4"}},{"t":"case","label":"Republic of Argentina v. Weltover, Inc.","cite":"504 U.S. 607","y":1992,"id":"1991/91-763","sc":1,"sum":"The Court held that the District Court properly asserted jurisdiction under the FSIA.","sumSrc":"Oyez","by":{"1":"22","2":"39"}},{"t":"case","label":"Republic of Iraq v. Beaty","cite":"556 U.S 848","y":2009,"url":"https://www.courtlistener.com/c/U.S/556/848/","by":{"1":"18, 26, 28, 29-31"}},{"t":"case","label":"Republic of Mexico v. Hoffman","cite":"324 U.S. 30","y":1945,"id":"scdb/1944-078","sc":1,"sum":"1. The decisions of the two courts below that the vessel in question was not in the possession or service of the Mexican government are supported by the evidence.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5, 26","2":"47"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"op":4,"sum":"The Court held that the Foreign Sovereign Immunities Act does not extend to an individual acting in his official capacity on behalf of the foreign state.","sumSrc":"Oyez","by":{"1":"5","2":"19","3":"13"}},{"t":"usc","label":"22 U.S.C. § 1643b","url":"https://www.law.cornell.edu/uscode/text/22/1643b","subs":["(a)"],"by":{"1":"7"}},{"t":"usc","label":"22 U.S.C. § 6022","url":"https://www.law.cornell.edu/uscode/text/22/6022","subs":["(3)","(6)"],"by":{"1":"20, 20"}},{"t":"usc","label":"22 U.S.C. § 6023","url":"https://www.law.cornell.edu/uscode/text/22/6023","subs":["(1)","(3)","(5)(A)","(11)","(13)(A)","(13)","(15)"],"stext":{"head":"§6023. Definitions","paras":[[0,"As used in this chapter, the following terms have the following meanings:"],[0,"(1) Agency or instrumentality of a foreign state"],[1,"The term \"agency or instrumentality of a foreign state\" has the meaning given that term in section 1603(b) of title 28."],[0,"(2) Appropriate congressional committees"],[1,"The term \"appropriate congressional committees\" means the Committee on International Relations and the Committee on Appropriations of the House of Representatives and the Committee on Foreign Relations and the Committee on Appropriations of the Senate."],[0,"(3) Commercial activity"],[1,"The term \"commercial activity\" has the meaning given that term in section 1603(d) of title 28."],[0,"(4) Confiscated"],[1,"As used in subchapters I and III, the term \"confiscated\" refers to—"],[2,"(A) the nationalization, expropriation, or other seizure by the Cuban Government of ownership or control of property, on or after January 1, 1959—"],[3,"(i) without the property having been returned or adequate and effective compensation provided; or"],[3,"(ii) without the claim to the property having been settled pursuant to an international claims settlement agreement or other mutually accepted settlement procedure; and"],[2,"(B) the repudiation by the Cuban Government of, the default by the Cuban Government on, or the failure of the Cuban Government to pay, on or after January 1, 1959—"],[3,"(i) a debt of any enterprise which has been nationalized, expropriated, or otherwise taken by the Cuban Government;"],[3,"(ii) a debt which is a charge on property nationalized, expropriated, or otherwise taken by the Cuban Government; or"],[3,"(iii) a debt which was incurred by the Cuban Government in satisfaction or settlement of a confiscated property claim."],[0,"(5) Cuban Government"],[1,"(A) The term \"Cuban Government\" includes the government of any political subdivision of Cuba, and any agency or instrumentality of the Government of Cuba."],[1,"(B) For purposes of subparagraph (A), the term \"agency or instrumentality of the Government of Cuba\" means an agency or instrumentality of a foreign state as defined in section 1603(b) of title 28, with each reference in such section to \"a foreign state\" deemed to be a reference to \"Cuba\"."],[0,"(6) Democratically elected government in Cuba"],[1,"The term \"democratically elected government in Cuba\" means a government determined by the President to have met the requirements of section 6066 of this title."],[0,"(7) Economic embargo of Cuba"],[1,"The term \"economic embargo of Cuba\" refers to—"],[2,"(A) the economic embargo (including all restrictions on trade or transactions with, and travel to or from, Cuba, and all restrictions on transactions in property in which Cuba or nationals of Cuba have an interest) that was imposed against Cuba pursuant to section 2370(a) of this title, section 4305(b) of title 50, the Cuban Democracy Act of 1992 (22 U.S.C. 6001 and following), or any other provision of law; and"],[2,"(B) the restrictions imposed by section 902(c) of the Food Security Act of 1985."],[0,"(8) Foreign national"],[1,"The term \"foreign national\" means—"],[2,"(A) an alien; or"],[2,"(B) any corporation, trust, partnership, or other juridical entity not organized under the laws of the United States, or of any State, the District of Columbia, or any commonwealth, territory, or possession of the United States."],[0,"(9) Knowingly"],[1,"The term \"knowingly\" means with knowledge or having reason to know."],[0,"(10) Official of the Cuban Government or the ruling political party in Cuba"],[1,"The term \"official of the Cuban Government or the ruling political party in Cuba\" refers to any member of the Council of Ministers, Council of State, central committee of the Communist Party of Cuba, or the Politburo of Cuba, or their equivalents."],[0,"(11) Person"],[1,"The term \"person\" means any person or entity, including any agency or instrumentality of a foreign state."],[0,"(12) Property"],[1,"(A) The term \"property\" means any property (including patents, copyrights, trademarks, and any other form of intellectual property), whether real, personal, or mixed, and any present, future, or contingent right, security, or other interest therein, including any leasehold interest."],[1,"(B) For purposes of subchapter III of this chapter, the term \"property\" does not include real property used for residential purposes unless, as of March 12, 1996—"],[2,"(i) the claim to the property is held by a United States national and the claim has been certified under title V of the International Claims Settlement Act of 1949 [22 U.S.C. 1643 et seq.]; or"],[2,"(ii) the property is occupied by an official of the Cuban Government or the ruling political party in Cuba."],[0,"(13) Traffics"],[1,"(A) As used in subchapter III, and except as provided in subparagraph (B), a person \"traffics\" in confiscated property if that person knowingly and intentionally—"],[2,"(i) sells, transfers, distributes, dispenses, brokers, manages, or otherwise disposes of confiscated property, or purchases, leases, receives, possesses, obtains control of, manages, uses, or otherwise acquires or holds an interest in confiscated property,"],[2,"(ii) engages in a commercial activity using or otherwise benefiting from confiscated property, or"],[2,"(iii) causes, directs, participates in, or profits from, trafficking (as described in clause (i) or (ii)) by another person, or otherwise engages in trafficking (as described in clause (i) or (ii)) through another person,"],[1,"without the authorization of any United States national who holds a claim to the property."],[1,"(B) The term \"traffics\" does not include—"],[2,"(i) the delivery of international telecommunication signals to Cuba;"],[2,"(ii) the trading or holding of securities publicly traded or held, unless the trading is with or by a person determined by the Secretary of the Treasury to be a specially designated national;"],[2,"(iii) transactions and uses of property incident to lawful travel to Cuba, to the extent that such transactions and uses of property are necessary to the conduct of such travel; or"],[2,"(iv) transactions and uses of property by a person who is both a citizen of Cuba and a resident of Cuba, and who is not an official of the Cuban Government or the ruling political party in Cuba."],[0,"(14) Transition government in Cuba"],[1,"The term \"transition government in Cuba\" means a government that the President determines is a transition government consistent with the requirements and factors set forth in section 6065 of this title."],[0,"(15) United States national"],[1,"The term \"United States national\" means—"],[2,"(A) any United States citizen; or"],[2,"(B) any other legal entity which is organized under the laws of the United States, or of any State, the District of Columbia, or any commonwealth, territory, or possession of the United States, and which has its principal place of business in the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/6023?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6023. Definitions","tname":"Foreign Relations and Intercourse","by":{"1":"25, 25, 19, 2, 6, 8, 14, 18, 8","2":"6-8, 28, 30, 7, 8, 28, 30, 8"}},{"t":"usc","label":"22 U.S.C. § 6032","url":"https://www.law.cornell.edu/uscode/text/22/6032","subs":["(h)"],"stext":{"head":"§6032. Enforcement of economic embargo of Cuba","paras":[[0,"(a) Policy"],[0,"(1) Restrictions by other countries"],[1,"The Congress hereby reaffirms section 1704(a) of the Cuban Democracy Act of 1992 [22 U.S.C. 6003(a)], which states that the President should encourage foreign countries to restrict trade and credit relations with Cuba in a manner consistent with the purposes of that Act [22 U.S.C. 6001 et seq.]."],[0,"(2) Sanctions on other countries"],[1,"The Congress further urges the President to take immediate steps to apply the sanctions described in section 1704(b)(1) of that Act [22 U.S.C. 6003(b)(1)] against countries assisting Cuba."],[0,"(b) Diplomatic efforts"],[0,"The Secretary of State should ensure that United States diplomatic personnel abroad understand and, in their contacts with foreign officials, are communicating the reasons for the United States economic embargo of Cuba, and are urging foreign governments to cooperate more effectively with the embargo."],[0,"(c) Existing regulations"],[0,"The President shall instruct the Secretary of the Treasury and the Attorney General to enforce fully the Cuban Assets Control Regulations set forth in part 515 of title 31, Code of Federal Regulations."],[0,"(d) Omitted"],[0,"(e) Denial of visas to certain Cuban nationals"],[0,"It is the sense of the Congress that the President should instruct the Secretary of State and the Attorney General to enforce fully existing regulations to deny visas to Cuban nationals considered by the Secretary of State to be officers or employees of the Cuban Government or of the Communist Party of Cuba."],[0,"(f), (g) Omitted"],[0,"(h) Codification of economic embargo"],[0,"The economic embargo of Cuba, as in effect on March 1, 1996, including all restrictions under part 515 of title 31, Code of Federal Regulations, shall be in effect on March 12, 1996, and shall remain in effect, subject to section 6064 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/6032?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§6032. Enforcement of economic embargo of Cuba","tname":"Foreign Relations and Intercourse","by":{"1":"3, 7, 15, 22, 34","2":"35"}},{"t":"usc","label":"22 U.S.C. § 6064","url":"https://www.law.cornell.edu/uscode/text/22/6064","subs":["(a)"],"stext":{"head":"§6064. Termination of economic embargo of Cuba","paras":[[0,"(a) Presidential actions"],[0,"Upon submitting a determination to the appropriate congressional committees under section 6063(c)(1) of this title that a transition government in Cuba is in power, the President, after consultation with the Congress, is authorized to take steps to suspend the economic embargo of Cuba and to suspend the right of action created in section 6082 of this title with respect to actions thereafter filed against the Cuban Government, to the extent that such steps contribute to a stable foundation for a democratically elected government in Cuba."],[0,"(b) Suspension of certain provisions of law"],[0,"In carrying out subsection (a), the President may suspend the enforcement of—"],[1,"(1) section 2370(a) of this title;"],[1,"(2) section 2370(f) of this title with respect to the \"Republic of Cuba\";"],[1,"(3) sections 6003, 6004(d), and 6005 of this title;"],[1,"(4) section 902(c) of the Food Security Act of 1985; and"],[1,"(5) the prohibitions on transactions described in part 515 of title 31, Code of Federal Regulations."],[0,"(c) Additional Presidential actions"],[0,"Upon submitting a determination to the appropriate congressional committees under section 6063(c)(3) of this title that a democratically elected government in Cuba is in power, the President shall take steps to terminate the economic embargo of Cuba, including the restrictions under part 515 of title 31, Code of Federal Regulations."],[0,"(d) Conforming amendments"],[0,"On the date on which the President submits a determination under section 6063(c)(3) of this title—"],[1,"(1) section 2370(a) of this title is repealed;"],[1,"(2) section 2370(f) of this title is amended by striking \"Republic of Cuba\";"],[1,"(3) sections 6003, 6004(d), and 6005 of this title are repealed; and"],[1,"(4) section 902(c) of the Food Security Act of 1985 is repealed."],[0,"(e) Review of suspension of economic embargo"],[0,"(1) Review"],[1,"If the President takes action under subsection (a) to suspend the economic embargo of Cuba, the President shall immediately so notify the Congress. The President shall report to the Congress no less frequently than every 6 months thereafter, until he submits a determination under section 6063(c)(3) of this title that a democratically elected government in Cuba is in power, on the progress being made by Cuba toward the establishment of such a democratically elected government. The action of the President under subsection (a) shall cease to be effective upon the enactment of a joint resolution described in paragraph (2)."],[0,"(2) Joint resolutions"],[1,"For purposes of this subsection, the term \"joint resolution\" means only a joint resolution of the 2 Houses of Congress, the matter after the resolving clause of which is as follows: \"That the Congress disapproves the action of the President under section 204(a) of the Cuban Liberty and Democratic Solidarity (LIBERTAD) Act of 1996 to suspend the economic embargo of Cuba, notice of which was submitted to the Congress on ____.\", with the blank space being filled with the appropriate date."],[0,"(3) Referral to committees"],[1,"Joint resolutions introduced in the House of Representatives shall be referred to the Committee on International Relations and joint resolutions introduced in the Senate shall be referred to the Committee on Foreign Relations."],[0,"(4) Procedures"],[1,"(A) Any joint resolution shall be considered in the Senate in accordance with the provisions of section 601(b) of the International Security Assistance and Arms Export Control Act of 1976."],[1,"(B) For the purpose of expediting the consideration and enactment of joint resolutions, a motion to proceed to the consideration of any joint resolution after it has been reported by the appropriate committee shall be treated as highly privileged in the House of Representatives."],[1,"(C) Not more than 1 joint resolution may be considered in the House of Representatives and the Senate in the 6-month period beginning on the date on which the President notifies the Congress under paragraph (1) of the action taken under subsection (a), and in each 6-month period thereafter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/6064?type=usc&year=mostrecent&link-type=html"},"head":"§6064. Termination of economic embargo of Cuba","tname":"Foreign Relations and Intercourse","by":{"1":"34, 8, 19","2":"48"}},{"t":"usc","label":"22 U.S.C. § 6065","url":"https://www.law.cornell.edu/uscode/text/22/6065","by":{"1":"19"}},{"t":"usc","label":"22 U.S.C. § 6081","url":"https://www.law.cornell.edu/uscode/text/22/6081","subs":["(2)","(3)","(5)","(6)","(8)","(10)","(11)"],"stext":{"head":"§6081. Findings","paras":[[0,"The Congress makes the following findings:"],[1,"(1) Individuals enjoy a fundamental right to own and enjoy property which is enshrined in the United States Constitution."],[1,"(2) The wrongful confiscation or taking of property belonging to United States nationals by the Cuban Government, and the subsequent exploitation of this property at the expense of the rightful owner, undermines the comity of nations, the free flow of commerce, and economic development."],[1,"(3) Since Fidel Castro seized power in Cuba in 1959—"],[2,"(A) he has trampled on the fundamental rights of the Cuban people; and"],[2,"(B) through his personal despotism, he has confiscated the property of—"],[3,"(i) millions of his own citizens;"],[3,"(ii) thousands of United States nationals; and"],[3,"(iii) thousands more Cubans who claimed asylum in the United States as refugees because of persecution and later became naturalized citizens of the United States."],[1,"(4) It is in the interest of the Cuban people that the Cuban Government respect equally the property rights of Cuban nationals and nationals of other countries."],[1,"(5) The Cuban Government is offering foreign investors the opportunity to purchase an equity interest in, manage, or enter into joint ventures using property and assets some of which were confiscated from United States nationals."],[1,"(6) This \"trafficking\" in confiscated property provides badly needed financial benefit, including hard currency, oil, and productive investment and expertise, to the current Cuban Government and thus undermines the foreign policy of the United States—"],[2,"(A) to bring democratic institutions to Cuba through the pressure of a general economic embargo at a time when the Castro regime has proven to be vulnerable to international economic pressure; and"],[2,"(B) to protect the claims of United States nationals who had property wrongfully confiscated by the Cuban Government."],[1,"(7) The United States Department of State has notified other governments that the transfer to third parties of properties confiscated by the Cuban Government \"would complicate any attempt to return them to their original owners\"."],[1,"(8) The international judicial system, as currently structured, lacks fully effective remedies for the wrongful confiscation of property and for unjust enrichment from the use of wrongfully confiscated property by governments and private entities at the expense of the rightful owners of the property."],[1,"(9) International law recognizes that a nation has the ability to provide for rules of law with respect to conduct outside its territory that has or is intended to have substantial effect within its territory."],[1,"(10) The United States Government has an obligation to its citizens to provide protection against wrongful confiscations by foreign nations and their citizens, including the provision of private remedies."],[1,"(11) To deter trafficking in wrongfully confiscated property, United States nationals who were the victims of these confiscations should be endowed with a judicial remedy in the courts of the United States that would deny traffickers any profits from economically exploiting Castro's wrongful seizures."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/6081?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§6081. Findings","tname":"Foreign Relations and Intercourse","by":{"1":"35, 3, 15, 3, 15, 18, 20, 3, 15, 18, 20, 35, 3, 7, 15, 18, 20, 34, 18, 3, 7, 15, 18, 20, 34","2":"7, 31-32, 31-32"}},{"t":"usc","label":"22 U.S.C. § 6082","url":"https://www.law.cornell.edu/uscode/text/22/6082","subs":["(a)(1)(A)","(a)(3)","(a)(6)","(a)(7)(B)","(c)(1)","(c)(2)","(d)","(h)(1)","(h)(1)(A)","(a)(1)","(c)","(e)"],"stext":{"head":"§6082. Liability for trafficking in confiscated property claimed by United States nationals","paras":[[0,"(a) Civil remedy"],[0,"(1) Liability for trafficking"],[1,"(A) Except as otherwise provided in this section, any person that, after the end of the 3-month period beginning on the effective date of this subchapter, traffics in property which was confiscated by the Cuban Government on or after January 1, 1959, shall be liable to any United States national who owns the claim to such property for money damages in an amount equal to the sum of—"],[2,"(i) the amount which is the greater of—"],[3,"(I) the amount, if any, certified to the claimant by the Foreign Claims Settlement Commission under the International Claims Settlement Act of 1949 [22 U.S.C. 1621 et seq.], plus interest;"],[3,"(II) the amount determined under section 6083(a)(2) of this title, plus interest; or"],[3,"(III) the fair market value of that property, calculated as being either the current value of the property, or the value of the property when confiscated plus interest, whichever is greater; and"],[2,"(ii) court costs and reasonable attorneys' fees."],[1,"(B) Interest under subparagraph (A)(i) shall be at the rate set forth in section 1961 of title 28, computed by the court from the date of confiscation of the property involved to the date on which the action is brought under this subsection."],[0,"(2) Presumption in favor of the certified claims"],[1,"There shall be a presumption that the amount for which a person is liable under clause (i) of paragraph (1)(A) is the amount that is certified as described in subclause (I) of that clause. The presumption shall be rebuttable by clear and convincing evidence that the amount described in subclause (II) or (III) of that clause is the appropriate amount of liability under that clause."],[0,"(3) Increased liability"],[1,"(A) Any person that traffics in confiscated property for which liability is incurred under paragraph (1) shall, if a United States national owns a claim with respect to that property which was certified by the Foreign Claims Settlement Commission under title V of the International Claims Settlement Act of 1949 [22 U.S.C. 1643 et seq.], be liable for damages computed in accordance with subparagraph (C)."],[1,"(B) If the claimant in an action under this subsection (other than a United States national to whom subparagraph (A) applies) provides, after the end of the 3-month period described in paragraph (1) notice to—"],[2,"(i) a person against whom the action is to be initiated, or"],[2,"(ii) a person who is to be joined as a defendant in the action,"],[1,"at least 30 days before initiating the action or joining such person as a defendant, as the case may be, and that person, after the end of the 30-day period beginning on the date the notice is provided, traffics in the confiscated property that is the subject of the action, then that person shall be liable to that claimant for damages computed in accordance with subparagraph (C)."],[1,"(C) Damages for which a person is liable under subparagraph (A) or subparagraph (B) are money damages in an amount equal to the sum of—"],[2,"(i) the amount determined under paragraph (1)(A)(ii), and"],[2,"(ii) 3 times the amount determined applicable under paragraph (1)(A)(i)."],[1,"(D) Notice to a person under subparagraph (B)—"],[2,"(i) shall be in writing;"],[2,"(ii) shall be posted by certified mail or personally delivered to the person; and"],[2,"(iii) shall contain—"],[3,"(I) a statement of intention to commence the action under this section or to join the person as a defendant (as the case may be), together with the reasons therefor;"],[3,"(II) a demand that the unlawful trafficking in the claimant's property cease immediately; and"],[3,"(III) a copy of the summary statement published under paragraph (8)."],[0,"(4) Applicability"],[1,"(A) Except as otherwise provided in this paragraph, actions may be brought under paragraph (1) with respect to property confiscated before, on, or after March 12, 1996."],[1,"(B) In the case of property confiscated before March 12, 1996, a United States national may not bring an action under this section on a claim to the confiscated property unless such national acquires ownership of the claim before March 12, 1996."],[1,"(C) In the case of property confiscated on or after March 12, 1996, a United States national who, after the property is confiscated, acquires ownership of a claim to the property by assignment for value, may not bring an action on the claim under this section."],[0,"(5) Treatment of certain actions"],[1,"(A) In the case of a United States national who was eligible to file a claim with the Foreign Claims Settlement Commission under title V of the International Claims Settlement Act of 1949 [22 U.S.C. 1643 et seq.] but did not so file the claim, that United States national may not bring an action on that claim under this section."],[1,"(B) In the case of any action brought under this section by a United States national whose underlying claim in the action was timely filed with the Foreign Claims Settlement Commission under title V of the International Claims Settlement Act of 1949 but was denied by the Commission, the court shall accept the findings of the Commission on the claim as conclusive in the action under this section."],[1,"(C) A United States national, other than a United States national bringing an action under this section on a claim certified under title V of the International Claims Settlement Act of 1949, may not bring an action on a claim under this section before the end of the 2-year period beginning on March 12, 1996."],[1,"(D) An interest in property for which a United States national has a claim certified under title V of the International Claims Settlement Act of 1949 may not be the subject of a claim in an action under this section by any other person. Any person bringing an action under this section whose claim has not been so certified shall have the burden of establishing for the court that the interest in property that is the subject of the claim is not the subject of a claim so certified."],[0,"(6) Inapplicability of act of state doctrine"],[1,"No court of the United States shall decline, based upon the act of state doctrine, to make a determination on the merits in an action brought under paragraph (1) ."],[0,"(7) Licenses not required"],[1,"(A) Notwithstanding any other provision of law, an action under this section may be brought and may be settled, and a judgment rendered in such action may be enforced, without obtaining any license or other permission from any agency of the United States, except that this paragraph shall not apply to the execution of a judgment against, or the settlement of actions involving, property blocked under the authorities of section 4305(b) of title 50, that were being exercised on July 1, 1977, as a result of a national emergency declared by the President before such date, and are being exercised on March 12, 1996."],[1,"(B) Notwithstanding any other provision of law, and for purposes of this subchapter only, any claim against the Cuban Government shall not be deemed to be an interest in property the transfer of which to a United States national required before March 12, 1996, or requires after March 12, 1996, a license issued by, or the permission of, any agency of the United States."],[0,"(8) Publication by Attorney General"],[1,"Not later than 60 days after March 12, 1996, the Attorney General shall prepare and publish in the Federal Register a concise summary of the provisions of this subchapter, including a statement of the liability under this subchapter of a person trafficking in confiscated property, and the remedies available to United States nationals under this subchapter."],[0,"(b) Amount in controversy"],[0,"An action may be brought under this section by a United States national only where the amount in controversy exceeds the sum or value of $50,000, exclusive of interest, costs, and attorneys' fees. In calculating $50,000 for purposes of the preceding sentence, the applicable amount under subclause (I), (II), or (III) of subsection (a)(1)(A)(i) may not be tripled as provided in subsection (a)(3)."],[0,"(c) Procedural requirements"],[0,"(1) In general"],[1,"Except as provided in this subchapter, the provisions of title 28 and the rules of the courts of the United States apply to actions under this section to the same extent as such provisions and rules apply to any other action brought under section 1331 of title 28."],[0,"(2) Service of process"],[1,"In an action under this section, service of process on an agency or instrumentality of a foreign state in the conduct of a commercial activity, or against individuals acting under color of law, shall be made in accordance with section 1608 of title 28."],[0,"(d) Enforceability of judgments against Cuban Government"],[0,"In an action brought under this section, any judgment against an agency or instrumentality of the Cuban Government shall not be enforceable against an agency or instrumentality of either a transition government in Cuba or a democratically elected government in Cuba."],[0,"(e) Omitted"],[0,"(f) Election of remedies"],[0,"(1) Election"],[1,"Subject to paragraph (2)—"],[2,"(A) any United States national that brings an action under this section may not bring any other civil action or proceeding under the common law, Federal law, or the law of any of the several States, the District of Columbia, or any commonwealth, territory, or possession of the United States, that seeks monetary or nonmonetary compensation by reason of the same subject matter; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/6082?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§6082. Liability for trafficking in confiscated property claimed by United States nationals","tname":"Foreign Relations and Intercourse","by":{"1":"2, 6, 8, 14, 18, 8, 32, 8, 19, 8, 9, 25, 9, 25, 3, 8, 14, 19, 24, 9, 19","2":"4, 30, 6-8, 8, 13, 26, 51, 45, 50, 53, 52, 53, 7, 8, 13, 26, 28"}},{"t":"usc","label":"22 U.S.C. § 6085","url":"https://www.law.cornell.edu/uscode/text/22/6085","subs":["(b)","(c)","(c)(1)(B)","(c)(2)","(c)(1)"],"stext":{"head":"§6085. Effective date","paras":[[0,"(a) In general"],[0,"Subject to subsections (b) and (c), this subchapter and the amendments made by this subchapter shall take effect on August 1, 1996."],[0,"(b) Suspension authority"],[0,"(1) Suspension authority"],[1,"The President may suspend the effective date under subsection (a) for a period of not more than 6 months if the President determines and reports in writing to the appropriate congressional committees at least 15 days before such effective date that the suspension is necessary to the national interests of the United States and will expedite a transition to democracy in Cuba."],[0,"(2) Additional suspensions"],[1,"The President may suspend the effective date under subsection (a) for additional periods of not more than 6 months each, each of which shall begin on the day after the last day of the period during which a suspension is in effect under this subsection, if the President determines and reports in writing to the appropriate congressional committees at least 15 days before the date on which the additional suspension is to begin that the suspension is necessary to the national interests of the United States and will expedite a transition to democracy in Cuba."],[0,"(c) Other authorities"],[0,"(1) Suspension"],[1,"After this subchapter and the amendments of this subchapter have taken effect—"],[2,"(A) no person shall acquire a property interest in any potential or pending action under this subchapter; and"],[2,"(B) the President may suspend the right to bring an action under this subchapter with respect to confiscated property for a period of not more than 6 months if the President determines and reports in writing to the appropriate congressional committees at least 15 days before the suspension takes effect that such suspension is necessary to the national interests of the United States and will expedite a transition to democracy in Cuba."],[0,"(2) Additional suspensions"],[1,"The President may suspend the right to bring an action under this subchapter for additional periods of not more than 6 months each, each of which shall begin on the day after the last day of the period during which a suspension is in effect under this subsection, if the President determines and reports in writing to the appropriate congressional committees at least 15 days before the date on which the additional suspension is to begin that the suspension is necessary to the national interests of the United States and will expedite a transition to democracy in Cuba."],[0,"(3) Pending suits"],[1,"The suspensions of actions under paragraph (1) shall not affect suits commenced before the date of such suspension, and in all such suits, proceedings shall be had, appeals taken, and judgments rendered in the same manner and with the same effect as if the suspension had not occurred."],[0,"(d) Rescission of suspension"],[0,"The President may rescind any suspension made under subsection (b) or (c) upon reporting to the appropriate congressional committees that doing so will expedite a transition to democracy in Cuba."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/6085?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6085. Effective date","tname":"Foreign Relations and Intercourse","by":{"1":"9, 4, 26, 9, 9","2":"8, 9, 28, 7, 14, 46"}},{"t":"law","label":"Pub. L. No. 108-11","url":"https://www.govinfo.gov/link/plaw/108/public/11","by":{"1":"31"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","by":{"1":"13","2":"16, 17"}},{"t":"usc","label":"15 U.S.C. § 1681n","url":"https://www.law.cornell.edu/uscode/text/15/1681n","subs":["(a)"],"by":{"1":"13"}},{"t":"usc","label":"15 U.S.C. § 1681o","url":"https://www.law.cornell.edu/uscode/text/15/1681o","subs":["(a)"],"by":{"1":"13"}},{"t":"usc","label":"28 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/28/1330","subs":["(a)","(b)"],"stext":{"head":"§1330. Actions against foreign states","paras":[[0,"(a) The district courts shall have original jurisdiction without regard to amount in controversy of any nonjury civil action against a foreign state as defined in section 1603(a) of this title as to any claim for relief in personam with respect to which the foreign state is not entitled to immunity either under sections 1605–1607 of this title or under any applicable international agreement."],[0,"(b) Personal jurisdiction over a foreign state shall exist as to every claim for relief over which the district courts have jurisdiction under subsection (a) where service has been made under section 1608 of this title."],[0,"(c) For purposes of subsection (b), an appearance by a foreign state does not confer personal jurisdiction with respect to any claim for relief not arising out of any transaction or occurrence enumerated in sections 1605–1607 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1330?type=usc&year=mostrecent&link-type=html"},"op":10,"ar":1,"head":"§1330. Actions against foreign states","tname":"Judiciary and Judicial Procedure","by":{"1":"1, 2, 6, 25, 6, 25","2":"4, 6, 44, 45, 47, 4, 6, 44, 45, 47","3":"12"}},{"t":"usc","label":"28 U.S.C. § 1391","url":"https://www.law.cornell.edu/uscode/text/28/1391","by":{"1":"11"}},{"t":"usc","label":"28 U.S.C. § 1603","url":"https://www.law.cornell.edu/uscode/text/28/1603","subs":["(a)","(b)"],"by":{"1":"5, 5","2":"6"}},{"t":"usc","label":"28 U.S.C. § 1604","url":"https://www.law.cornell.edu/uscode/text/28/1604","stext":{"head":"§1604. Immunity of a foreign state from jurisdiction","paras":[[0,"Subject to existing international agreements to which the United States is a party at the time of enactment of this Act a foreign state shall be immune from the jurisdiction of the courts of the United States and of the States except as provided in sections 1605 to 1607 of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1604?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":2,"head":"§1604. Immunity of a foreign state from jurisdiction","tname":"Judiciary and Judicial Procedure","by":{"1":"5","2":"4"}},{"t":"usc","label":"28 U.S.C. § 1605","url":"https://www.law.cornell.edu/uscode/text/28/1605","subs":["(a)(2)","(a)(3)","(a)(4)","(a)(5)","(b)","(a)(6)","(a)(7)"],"stext":{"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","paras":[[0,"(a) A foreign state shall not be immune from the jurisdiction of courts of the United States or of the States in any case—"],[1,"(1) in which the foreign state has waived its immunity either explicitly or by implication, notwithstanding any withdrawal of the waiver which the foreign state may purport to effect except in accordance with the terms of the waiver;"],[1,"(2) in which the action is based upon a commercial activity carried on in the United States by the foreign state; or upon an act performed in the United States in connection with a commercial activity of the foreign state elsewhere; or upon an act outside the territory of the United States in connection with a commercial activity of the foreign state elsewhere and that act causes a direct effect in the United States;"],[1,"(3) in which rights in property taken in violation of international law are in issue and that property or any property exchanged for such property is present in the United States in connection with a commercial activity carried on in the United States by the foreign state; or that property or any property exchanged for such property is owned or operated by an agency or instrumentality of the foreign state and that agency or instrumentality is engaged in a commercial activity in the United States;"],[1,"(4) in which rights in property in the United States acquired by succession or gift or rights in immovable property situated in the United States are in issue;"],[1,"(5) not otherwise encompassed in paragraph (2) above, in which money damages are sought against a foreign state for personal injury or death, or damage to or loss of property, occurring in the United States and caused by the tortious act or omission of that foreign state or of any official or employee of that foreign state while acting within the scope of his office or employment; except this paragraph shall not apply to—"],[2,"(A) any claim based upon the exercise or performance or the failure to exercise or perform a discretionary function regardless of whether the discretion be abused, or"],[2,"(B) any claim arising out of malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights; or"],[1,"(6) in which the action is brought, either to enforce an agreement made by the foreign state with or for the benefit of a private party to submit to arbitration all or any differences which have arisen or which may arise between the parties with respect to a defined legal relationship, whether contractual or not, concerning a subject matter capable of settlement by arbitration under the laws of the United States, or to confirm an award made pursuant to such an agreement to arbitrate, if (A) the arbitration takes place or is intended to take place in the United States, (B) the agreement or award is or may be governed by a treaty or other international agreement in force for the United States calling for the recognition and enforcement of arbitral awards, (C) the underlying claim, save for the agreement to arbitrate, could have been brought in a United States court under this section or section 1607, or (D) paragraph (1) of this subsection is otherwise applicable."],[0,"(b) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any case in which a suit in admiralty is brought to enforce a maritime lien against a vessel or cargo of the foreign state, which maritime lien is based upon a commercial activity of the foreign state: Provided, That—"],[1,"(1) notice of the suit is given by delivery of a copy of the summons and of the complaint to the person, or his agent, having possession of the vessel or cargo against which the maritime lien is asserted; and if the vessel or cargo is arrested pursuant to process obtained on behalf of the party bringing the suit, the service of process of arrest shall be deemed to constitute valid delivery of such notice, but the party bringing the suit shall be liable for any damages sustained by the foreign state as a result of the arrest if the party bringing the suit had actual or constructive knowledge that the vessel or cargo of a foreign state was involved; and"],[1,"(2) notice to the foreign state of the commencement of suit as provided in section 1608 of this title is initiated within ten days either of the delivery of notice as provided in paragraph (1) of this subsection or, in the case of a party who was unaware that the vessel or cargo of a foreign state was involved, of the date such party determined the existence of the foreign state's interest."],[0,"(c) Whenever notice is delivered under subsection (b)(1), the suit to enforce a maritime lien shall thereafter proceed and shall be heard and determined according to the principles of law and rules of practice of suits in rem whenever it appears that, had the vessel been privately owned and possessed, a suit in rem might have been maintained. A decree against the foreign state may include costs of the suit and, if the decree is for a money judgment, interest as ordered by the court, except that the court may not award judgment against the foreign state in an amount greater than the value of the vessel or cargo upon which the maritime lien arose. Such value shall be determined as of the time notice is served under subsection (b)(1). Decrees shall be subject to appeal and revision as provided in other cases of admiralty and maritime jurisdiction. Nothing shall preclude the plaintiff in any proper case from seeking relief in personam in the same action brought to enforce a maritime lien as provided in this section."],[0,"(d) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any action brought to foreclose a preferred mortgage, as defined in section 31301 of title 46. Such action shall be brought, heard, and determined in accordance with the provisions of chapter 313 of title 46 and in accordance with the principles of law and rules of practice of suits in rem, whenever it appears that had the vessel been privately owned and possessed a suit in rem might have been maintained."],[0,"[(e), (f) Repealed. Pub. L. 110–181, div. A, title X, §1083(b)(1)(B), Jan. 28, 2008, 122 Stat. 341.]"],[0,"(g) Limitation on Discovery.—"],[1,"(1) In general.—(A) Subject to paragraph (2), if an action is filed that would otherwise be barred by section 1604, but for section 1605A or section 1605B, the court, upon request of the Attorney General, shall stay any request, demand, or order for discovery on the United States that the Attorney General certifies would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action, until such time as the Attorney General advises the court that such request, demand, or order will no longer so interfere."],[1,"(B) A stay under this paragraph shall be in effect during the 12-month period beginning on the date on which the court issues the order to stay discovery. The court shall renew the order to stay discovery for additional 12-month periods upon motion by the United States if the Attorney General certifies that discovery would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action."],[1,"(2) Sunset.—(A) Subject to subparagraph (B), no stay shall be granted or continued in effect under paragraph (1) after the date that is 10 years after the date on which the incident that gave rise to the cause of action occurred."],[1,"(B) After the period referred to in subparagraph (A), the court, upon request of the Attorney General, may stay any request, demand, or order for discovery on the United States that the court finds a substantial likelihood would—"],[2,"(i) create a serious threat of death or serious bodily injury to any person;"],[2,"(ii) adversely affect the ability of the United States to work in cooperation with foreign and international law enforcement agencies in investigating violations of United States law; or"],[2,"(iii) obstruct the criminal case related to the incident that gave rise to the cause of action or undermine the potential for a conviction in such case."],[1,"(3) Evaluation of evidence.—The court's evaluation of any request for a stay under this subsection filed by the Attorney General shall be conducted ex parte and in camera."],[1,"(4) Bar on motions to dismiss.—A stay of discovery under this subsection shall constitute a bar to the granting of a motion to dismiss under rules 12(b)(6) and 56 of the Federal Rules of Civil Procedure."],[1,"(5) Construction.—Nothing in this subsection shall prevent the United States from seeking protective orders or asserting privileges ordinarily available to the United States."],[0,"(h) Jurisdictional Immunity for Certain Art Exhibition Activities.—"],[1,"(1) In general.—If—"],[2,"(A) a work is imported into the United States from any foreign state pursuant to an agreement that provides for the temporary exhibition or display of such work entered into between a foreign state that is the owner or custodian of such work and the United States or one or more cultural or educational institutions within the United States;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","tname":"Judiciary and Judicial Procedure","by":{"1":"6, 6, 12, 15, 22, 23, 34, 6, 12, 15, 24, 34, 21, 22, 22","2":"6, 22, 24, 29, 40, 5, 5, 22, 23, 22"}},{"t":"usc","label":"28 U.S.C. § 1605A","url":"https://www.law.cornell.edu/uscode/text/28/1605A","by":{"1":"22","2":"40, 47"}},{"t":"usc","label":"28 U.S.C. § 1605B","url":"https://www.law.cornell.edu/uscode/text/28/1605B","by":{"1":"22"}},{"t":"usc","label":"28 U.S.C. § 1606","url":"https://www.law.cornell.edu/uscode/text/28/1606","by":{"1":"6"}},{"t":"usc","label":"28 U.S.C. § 1608","url":"https://www.law.cornell.edu/uscode/text/28/1608","stext":{"head":"§1608. Service; time to answer; default","paras":[[0,"(a) Service in the courts of the United States and of the States shall be made upon a foreign state or political subdivision of a foreign state:"],[1,"(1) by delivery of a copy of the summons and complaint in accordance with any special arrangement for service between the plaintiff and the foreign state or political subdivision; or"],[1,"(2) if no special arrangement exists, by delivery of a copy of the summons and complaint in accordance with an applicable international convention on service of judicial documents; or"],[1,"(3) if service cannot be made under paragraphs (1) or (2), by sending a copy of the summons and complaint and a notice of suit, together with a translation of each into the official language of the foreign state, by any form of mail requiring a signed receipt, to be addressed and dispatched by the clerk of the court to the head of the ministry of foreign affairs of the foreign state concerned, or"],[1,"(4) if service cannot be made within 30 days under paragraph (3), by sending two copies of the summons and complaint and a notice of suit, together with a translation of each into the official language of the foreign state, by any form of mail requiring a signed receipt, to be addressed and dispatched by the clerk of the court to the Secretary of State in Washington, District of Columbia, to the attention of the Director of Special Consular Services—and the Secretary shall transmit one copy of the papers through diplomatic channels to the foreign state and shall send to the clerk of the court a certified copy of the diplomatic note indicating when the papers were transmitted."],[0,"As used in this subsection, a \"notice of suit\" shall mean a notice addressed to a foreign state and in a form prescribed by the Secretary of State by regulation."],[0,"(b) Service in the courts of the United States and of the States shall be made upon an agency or instrumentality of a foreign state:"],[1,"(1) by delivery of a copy of the summons and complaint in accordance with any special arrangement for service between the plaintiff and the agency or instrumentality; or"],[1,"(2) if no special arrangement exists, by delivery of a copy of the summons and complaint either to an officer, a managing or general agent, or to any other agent authorized by appointment or by law to receive service of process in the United States; or in accordance with an applicable international convention on service of judicial documents; or"],[1,"(3) if service cannot be made under paragraphs (1) or (2), and if reasonably calculated to give actual notice, by delivery of a copy of the summons and complaint, together with a translation of each into the official language of the foreign state—"],[2,"(A) as directed by an authority of the foreign state or political subdivision in response to a letter rogatory or request or"],[2,"(B) by any form of mail requiring a signed receipt, to be addressed and dispatched by the clerk of the court to the agency or instrumentality to be served, or"],[2,"(C) as directed by order of the court consistent with the law of the place where service is to be made."],[0,"(c) Service shall be deemed to have been made—"],[1,"(1) in the case of service under subsection (a)(4), as of the date of transmittal indicated in the certified copy of the diplomatic note; and"],[1,"(2) in any other case under this section, as of the date of receipt indicated in the certification, signed and returned postal receipt, or other proof of service applicable to the method of service employed."],[0,"(d) In any action brought in a court of the United States or of a State, a foreign state, a political subdivision thereof, or an agency or instrumentality of a foreign state shall serve an answer or other responsive pleading to the complaint within sixty days after service has been made under this section."],[0,"(e) No judgment by default shall be entered by a court of the United States or of a State against a foreign state, a political subdivision thereof, or an agency or instrumentality of a foreign state, unless the claimant establishes his claim or right to relief by evidence satisfactory to the court. A copy of any such default judgment shall be sent to the foreign state or political subdivision in the manner prescribed for service in this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1608?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1608. Service; time to answer; default","tname":"Judiciary and Judicial Procedure","by":{"1":"6, 9, 25","2":"52, 53"}},{"t":"usc","label":"28 U.S.C. § 1609","url":"https://www.law.cornell.edu/uscode/text/28/1609","stext":{"head":"§1609. Immunity from attachment and execution of property of a foreign state","paras":[[0,"Subject to existing international agreements to which the United States is a party at the time of enactment of this Act the property in the United States of a foreign state shall be immune from attachment 1 arrest 1 and execution except as provided in sections 1610 and 1611 of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1609?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1609. Immunity from attachment and execution of property of a foreign state","tname":"Judiciary and Judicial Procedure","by":{"1":"6","2":"29"}},{"t":"usc","label":"28 U.S.C. § 1610","url":"https://www.law.cornell.edu/uscode/text/28/1610","subs":["(a)(2)","(b)(2)"],"by":{"1":"27, 27, 6","2":"22, 29, 29"}},{"t":"usc","label":"28 U.S.C. § 1611","url":"https://www.law.cornell.edu/uscode/text/28/1611","subs":["(c)"],"by":{"1":"9, 31","2":"22, 7"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","stext":{"head":"§1331. Federal question","paras":[[0,"The district courts shall have original jurisdiction of all civil actions arising under the Constitution, laws, or treaties of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1331?type=usc&year=mostrecent&link-type=html"},"op":17,"ar":3,"head":"§1331. Federal question","tname":"Judiciary and Judicial Procedure","by":{"1":"25","2":"44, 45, 51"}},{"t":"law","label":"Pub. L. No. 110-181","url":"https://www.govinfo.gov/link/plaw/110/public/181","by":{"1":"26"}},{"t":"law","label":"Pub. L. No. 107-297","url":"https://www.govinfo.gov/link/plaw/107/public/297","by":{"1":"27"}},{"t":"reg","label":"15 C.F.R. § 785.1","url":"https://www.ecfr.gov/current/title-15/section-785.1","subs":["(a)"],"by":{"1":"23"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"581 U.S. 468","y":2017,"id":"2016/16-74","sc":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Agency Holding Corp. v. Malley-Duff & Assocs., Inc.","cite":"483 U.S. 143","y":1987,"id":"1986/86-497","sc":1,"sum":"In February 1978, petitioner Crown Life Insurance Co. terminated its relationship with its agent, respondent Malley-Duff & Associates (MalleyDuff), for failure to satisfy a production quota. Alleging, inter alia, that the real reason for the termination was petitioners' desire to acquire its lucrative territory, Malley-Duff brought suit in March 1981 under the Racketeer Influenced and Corrupt Organizations Act …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"50"}},{"t":"case","label":"Agudas Chasidei Chabad of U.S. v. Russian Fed’n","cite":"528 F.3d 934","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/528/934/","by":{"2":"39"}},{"t":"case","label":"Alejandre v. Telefonica Larga Distancia, de P.R., Inc.","cite":"183 F.3d 1277","y":1999,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/183/1277/","by":{"2":"36"}},{"t":"case","label":"Altmann v. Republic of Austria","cite":"317 F.3d 954","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/317/954/","by":{"2":"39"}},{"t":"case","label":"Am. Nat’l Red Cross v. S.G.","cite":"505 U.S. 247","y":1992,"id":"1991/91-594","sc":1,"sum":"This holding leaves the jurisdiction of the federal courts well within the Article III limits, because the Court has consistently held that Article III's \"arising under\" jurisdiction is broad enough to authorize Congress to confer federal-court jurisdiction over actions involving federally chartered corporations.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Azar v. Alina Health Servs.","cite":"587 U.S. 566","y":2019,"url":"https://supreme.justia.com/cases/federal/us/587/566/","sc":1,"sum":"Finding Congress’ omission of “express[]” text in one statute when it “recently” included it in another was “intentional[] and purposeful[]”.","sumSrc":"brief:2","by":{"2":"23"}},{"t":"case","label":"Belhas v. Ya’alon","cite":"515 F.3d 1279","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/515/1279/","by":{"2":"19"}},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"47"}},{"t":"case","label":"Cited Authorities Page Blanchette v. Conn. Gen. Ins. Corps.","cite":"419 U.S. 102","y":1974,"id":"1974/74-165","sc":1,"sum":"As a comprehensive solution to a national rail crisis precipitated by the entry into reorganization proceedings under § 77 of the Bankruptcy Act of eight major railroads in the northeast and midwest region of the country, Congress supplemented § 77 with the Regional Rail Reorganization Act of 1973 (Rail Act). Each railroad under a § 77 reorganization must proceed under the Rail Act unless its reorganization court …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Blatchford v. Native Village of Noatak","cite":"501 U.S. 775","y":1991,"id":"1990/89-1782","sc":1,"sum":"Respondents, Alaska Native villages, brought suit against petitioner, a state official, seeking an order requiring payment to them of money allegedly owed under a state revenue-sharing statute. The District Court dismissed the suit as violating the Eleventh Amendment. The Court of Appeals reversed, first on the ground that 28 U. S. C. § 1362 constituted a congressional abrogation of Eleventh Amendment immunity, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"44"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne Int’l Drilling Co.","cite":"581 U.S. 170","y":2017,"url":"https://supreme.justia.com/cases/federal/us/581/170/","sc":1,"op":1,"by":{"2":"41-43"}},{"t":"case","label":"Broidy Capital Mgmt., LLC v. State of Qatar","cite":"982 F.3d 582","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/982/582/","by":{"2":"21"}},{"t":"case","label":"Browning-Ferris Indus. Of Vt., Inc. v. Kelco Disposal, Inc.","cite":"492 U.S. 257","y":1989,"id":"1988/88-556","sc":1,"sum":"Respondents Joseph Kelley and Kelco Disposal, Inc., filed suit against petitioners (collectively BFI) in Federal District Court, charging BFI with antitrust violations and with interfering with Kelco's contractual relations in violation of Vermont tort law. A jury found BFI liable on both counts, and awarded Kelco, in addition to $51,146 in compensatory damages, $6 million in punitive damages on the state-law claim. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"Bufkin v. Collins","cite":"604 U.S. 369","y":2025,"url":"https://supreme.justia.com/cases/federal/us/604/369/","sc":1,"by":{"2":"53"}},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"op":1,"ar":2,"sum":"The Court found that only tribes under federal jurisdiction at the time of the Indian Reorganization Act of 1934 are subject to taking by the federal government.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Chuidian v. Philippine Nat. Bank","cite":"912 F.2d 1095","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/912/1095/","sum":"Finding “official capacity” covered by FSIA but noting “ambigu[ity] as to its extension to individual foreign officials” and “significant support” for U.S. Government view that individuals not covered.","sumSrc":"brief:2","by":{"2":"52, 53"}},{"t":"case","label":"City of Arlington, Tex. v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"2":"50"}},{"t":"case","label":"Cited Authorities Page City of Chicago v. Env’t Def. Fund","cite":"511 U.S. 328","y":1994,"id":"1993/92-1639","sc":1,"sum":"Section 3001(i) does not exempt the MWC ash generated by petitioners' facility from Subtitle C regulation as hazardoug waste. Although a pre-§ 3001(i) EPA regulation provided a \"waste stream\" exemption covering household waste from generation through treatment to final disposal of residues, petitioners' facility would not have come within that exemption because it burned something in addition to household waste; the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26, 48"}},{"t":"case","label":"Connecticut Nat. Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"53"}},{"t":"case","label":"Credit Suisse Sec. (USA) LLC v. Billing","cite":"551 U.S. 264","y":2007,"id":"2006/05-1157","sc":1,"op":1,"sum":"The Court reversed the Second Circuit and ruled that the applicable securities laws granted the defendant implied antitrust immunity. The 7-1 ruling by Justice Stephen G. Breyer noted four factors indicating that the Securities Act of 1933 foreclosed antitrust lawsuits in cases of alleged artificial inflation of aftermarket IPO share prices.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"D.C. v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"sum":"The Court found a District of Columbia law strictly regulating gun ownership to be unconstitutional.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Dice v. Akron, Canton & Youngstown R. Co.","cite":"342 U.S. 359","y":1952,"id":"scdb/1951-039","sc":1,"sum":".1. In an action in a state court under the Federal Employers' Liability Act, the question of the validity of a release granted to the carrier by the injured employee is a federal question and is to be determined by federal rather than state law.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"50"}},{"t":"case","label":"Dir., Off. of Workers’ Comp. Programs, Dep’t of Labor v. Newport News Shipbuilding & Dry Dock Co.","cite":"514 U.S. 122","y":1995,"id":"1994/93-1783","sc":1,"sum":"The Director is not \"adversely affected or aggrieved\" under §921(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Does 1-5 v. Obiano","cite":"138 F.4th 955","y":2025,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/138/955/","ar":2,"by":{"2":"19"}},{"t":"case","label":"Dogan v. Barak","cite":"932 F.3d 888","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/932/888/","by":{"2":"19"}},{"t":"case","label":"El-Fadl v. Central Bank of Jordan","cite":"75 F.3d 668","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/75/668/","by":{"2":"52"}},{"t":"case","label":"Cited Authorities Page Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"url":"https://supreme.justia.com/cases/federal/us/584/497/","sc":1,"by":{"2":"21, 45"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Fed. Republic of Germany v. Philipp","cite":"592 U.S. 169","y":2021,"url":"https://supreme.justia.com/cases/federal/us/592/169/","sc":1,"by":{"2":"41"}},{"t":"case","label":"Fernandez v. Seaboard Marine","cite":"135 F.4th 939","y":2025,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/135/939/","by":{"2":"31"}},{"t":"case","label":"Filetech S.A. v. France Telecom S.A.","cite":"157 F.3d 922","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/157/922/","by":{"2":"22"}},{"t":"case","label":"Fla. Dep’t of Revenue v. Piccadilly Cafeterias, Inc.","cite":"554 U.S. 33","y":2008,"id":"2007/07-312","sc":1,"sum":"The Court held 7-2 that the plain meaning of the statute indicates that it only applies to confirmed asset sales, not \"pre-confirmation\" sales.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Garland v. Cargill","cite":"602 U.S. 406","y":2024,"id":"2023/22-976","sc":1,"sum":"The Bureau of Alcohol, Tobacco, Firearms and Explosives exceeded its statutory authority by issuing a Rule that classifies a bump stock as a “machinegun” under 26 U. S. C. §5845(b).","sumSrc":"Holding (supremecourt.gov)","by":{"2":"28"}},{"t":"case","label":"Glen v. Club Mediterranee, S.A.","cite":"450 F.3d 1251","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/450/1251/","by":{"2":"8"}},{"t":"case","label":"Cited Authorities Page Gomez v. United States","cite":"490 U.S. 858","y":1989,"id":"1988/88-5014","sc":1,"sum":"A Magistrate assigned by the District Judge conducted the voir dire examination and jury selection for petitioners' trial on multiple felony counts. The judge overruled petitioners' objections to the assignment of the Magistrate. The judge offered to review any of the Magistrate's rulings de novo, but petitioners registered no specific challenge to the selection of any juror. After petitioners were convicted and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Gordon v. N.Y. Stock Exch.","cite":"422 U.S. 659","y":1975,"id":"1974/74-304","sc":1,"sum":"The Supreme Court held that the Securities and Exchange Act of 1934 impliedly repealed any applicable antitrust laws. The Act authorized the Securities and Exchange Commission as the sole regulator for the New York Stock Exchange. Justice William O. Douglas wrote a concurrence, stating that the SEC has actively exercised its authority so commission rates are monitored in the way Congress intended.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Gross v. FBL Fin. Servs., Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"op":1,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Herbage v. Meese","cite":"747 F. Supp. 60","y":1990,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./747/60/","by":{"2":"52"}},{"t":"case","label":"Imbler v. Pachtman","cite":"424 U.S. 409","y":1976,"id":"1975/74-5435","sc":1,"sum":"The Court held that prosecutors have the same absolute immunity under Section 1983 that they had under common law in malicious prosecution suits.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"Jones v. Harris Assocs. L.P.","cite":"559 U.S. 335","y":2010,"id":"2009/08-586","sc":1,"sum":"The Court held that Section 36(b) of the Investment Company Act requires a determination that the financial adviser charges a fee that is \"so disproportionately large is bears no reasonable relationship to the services rendered\" before legal action may be taken.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Kingdomware Techs. Inc., v. United States","cite":"579 U.S. 162","y":2016,"id":"2015/14-916","sc":1,"sum":"The Court determined that the Court had jurisdiction to address the merits of the case even if the contracts had already been performed, and the Department of Veterans Affairs’ “set-aside” for veteran-owned businesses is mandatory.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"569 U.S. 108","y":2013,"id":"2011/10-1491","sc":1,"sum":"The Court found that the Alien Tort Statute does not give ground for United States law to be applied extraterrestrially to other sovereign nations with their own laws.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Lac du Flambeau Band of Lake Superior Chippewa Indians v. Coughlin","cite":"599 U.S. 382","y":2023,"id":"2022/22-227","sc":1,"op":1,"sum":"The Bankruptcy Code unequivocally abrogates the sovereign immunity of all governments, including federally recognized Indian tribes.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"15, 17-18, 31"}},{"t":"case","label":"Cited Authorities Page Lewis v. Mutond","cite":"918 F.3d 142","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/918/142/","by":{"2":"19"}},{"t":"case","label":"Lightfoot v. Cendant Mortg. Corp.","cite":"580 U.S. 82","y":2017,"id":"2016/14-1055","sc":1,"sum":"The Court determined that language in the federal charter of the Federal National Mortgage Association (Fannie Mae) that authorizes the organization to sue and be sued does not mean that federal courts have subject matter jurisdiction over any case in which Fannie Mae is a plaintiff or defendant, and the Supreme Court’s precedent in American National Red Cross v. S.G. doe not require a different result.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Luna Perez v. Sturgis Pub. Sch.","cite":"598 U.S. 142","y":2023,"id":"2022/21-887","sc":1,"op":5,"sum":"An Americans with Disabilities Act lawsuit seeking compensatory damages for the denial of a free and appropriate education may proceed without exhausting the administrative processes of the Individuals with Disabilities Education Act, 20 U. S. C. §1415(l), because the remedy sought is not one IDEA provides.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"28"}},{"t":"case","label":"Manoharan v. Rajapaksa","cite":"711 F.3d 178","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/711/178/","by":{"2":"19"}},{"t":"case","label":"Markham v. Cabell","cite":"326 U.S. 404","y":1945,"id":"scdb/1945-001","sc":1,"sum":"1. Section 9 (a) of the Trading with the Enemy Act allows \"Any person not an enemy or ally of enemy...to whom any debt may be owing from an enemy or ally of enemy whose property or any part thereof shall have been conveyed, transferred, assigned, delivered, or paid to the Alien Property Custodian\" to sue the Custodian or the Treasurer of the United States in the federal courts. Section 9 (e) provides that no debt …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26"}},{"t":"case","label":"Matar v. Dichter","cite":"563 F.3d 9","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/563/9/","by":{"2":"19"}},{"t":"case","label":"McLaughlin Chiropractic Assocs., Inc. v. McKesson Corp.","cite":"606 U.S. 146","y":2025,"id":"2024/23-1226","sc":1,"sum":"The Hobbs Act does not bind district courts in civil enforcement proceedings to an agency’s interpretation of a statute. District courts must independently determine the law’s meaning under ordinary principles of statutory interpretation while affording appropriate respect to the agency’s interpretation.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"17"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Mims v. Arrow Fin Serv., LLC","cite":"565 U.S. 368","y":2012,"id":"2011/10-1195","sc":1,"sum":"The Court held that the Telephone Consumer Protection Act does not strip federal courts of the ability to hear cases that would normally be brought in state courts.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Cited Authorities Page Nat’l Ass’n of Home Builders v. Defs. of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"2":"20, 21","3":"6"}},{"t":"case","label":"Nat’l Pork Producers Council v. Ross","cite":"598 U.S. 356","y":2023,"id":"2022/21-468","sc":1,"op":5,"sum":"The judgment of the Court of Appeals for the Ninth Circuit—affirming the dismissal of a complaint challenging California’s Proposition 12 under a dormant Commerce Clause rationale not grounded in an allegation that the law purposefully discriminates against out-of-state economic interests—is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"34"}},{"t":"case","label":"North American Sugar Indus., Inc. v. Xinjiang Goldwin Sci. & Tech. Co., Ltd","cite":"124 F.4th 1322","y":2025,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/124/1322/","by":{"2":"30-31"}},{"t":"case","label":"Oscar Mayer & Co. v. Evans","cite":"441 U.S. 750","y":1979,"id":"1978/78-275","sc":1,"sum":"Section 14 (b) of the Age Discrimination in Employment Act of 1967 (ADEA) provides that in the case of an alleged unlawful practice occurring in a State which has a law prohibiting discrimination in employment because of age and authorizing a state authority to grant and seek relief from such discriminatory practice, no suit may be brought under § 7 (c) of the ADEA before the expiration of 60 days after proceedings …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"50-51"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"465 U.S. 89","y":1984,"id":"1982/81-2101","sc":1,"sum":"The Eleventh Amendment prohibited the District Court from ordering state officials to conform their conduct to state law.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"POM Wonderful LLC v. Coca-Cola Co.","cite":"573 U.S. 102","y":2014,"id":"2013/12-761","sc":1,"sum":"The Court held that it is the duty of the court system to harmonize statutes, and that barring one applicable statute by use of another represents a disregard of the law's intent of having cooperative statutes.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Procunier v. Navarette","cite":"434 U.S. 555","y":1978,"id":"1977/76-446","sc":1,"sum":"The Court of Appeals erred in reversing the District Court's summary judgment for petitioners.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"Regan v. Wald","cite":"468 U.S. 222","y":1984,"id":"1983/83-436","sc":1,"sum":"Treasury Department Regulation 201(b), first promulgated in 1963 as part of the Cuban Assets Control Regulations, prohibits any transaction involving property in which Cuba, or any national thereof, has \"any interest of any nature whatsoever, direct or indirect.\" Regulation 560, which was added to the Regulations in 1977, embodied a general license permitting, for the most part, travel-related economic transactions …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"36"}},{"t":"case","label":"Regueiro v. American Airlines, Inc.","cite":"147 F.4th 1281","y":2025,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/147/1281/","by":{"2":"31"}},{"t":"case","label":"Cited Authorities Page Rehberg v. Paulk","cite":"566 U.S. 356","y":2012,"id":"2011/10-788","sc":1,"sum":"The Court held that a witness in a grand jury proceeding is entitled to the same absolute immunity from a §1983 action as a witness who testifies at trial.","sumSrc":"Oyez","by":{"2":"18, 19"}},{"t":"case","label":"Republic of Hungary v. Simon","cite":"604 U.S. 115","y":2025,"id":"2024/23-867","sc":1,"sum":"An allegation that a foreign sovereign liquidated expropriated property, commingled the proceeds with other funds, and then used some of those commingled funds for commercial activities in the United States cannot alone satisfy the commercial nexus requirement of the expropriation exception in the Foreign Sovereign Immunities Act of 1976.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"40-42","3":"8"}},{"t":"case","label":"Republic of Iraq v. Beaty","cite":"556 U.S. 848","y":2009,"id":"2008/07-1090","sc":1,"op":1,"by":{"2":"31, 47, 48","3":"5, 6"}},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"587 U.S. 1","y":2019,"id":"2018/16-1094","sc":1,"sum":"When civil process is served on a foreign state under the Foreign Sovereign Immunities Act of 1976, 28 U. S. C. §1608(a)(3) requires a mailing to be sent directly to the foreign minister’s office in the foreign state.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"23, 25"}},{"t":"case","label":"Rimini Street, Inc. v. Oracle USA, Inc.","cite":"586 U.S. 334","y":2019,"id":"2018/17-1625","sc":1,"sum":"A federal district court’s discretion to award “full costs” to a party in copyright litigation pursuant to 17 U. S. C. §505 is limited to the six categories specified in the general costs statute codified at 28 U. S. C. §§1821 and 1920.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"53"}},{"t":"case","label":"RJR Nabisco v. Eur. Cmty.","cite":"579 U.S. 325","y":2016,"id":"2015/15-138","sc":1,"sum":"The Court held that some sections of the Racketeer Influenced Corrupt Organizations (RICO) statute can apply extraterritorially because Congress clearly based them on predicate offenses that can occur outside of the United States.","sumSrc":"Oyez","by":{"2":"33, 42"}},{"t":"case","label":"Cited Authorities Page Rubin v. Islamic Republic of Iran","cite":"583 U.S. 202","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/202/","sc":1,"by":{"2":"23, 40, 41"}},{"t":"case","label":"Schansman v. Sberbank of Russia PJSC","cite":"128 F.4th 70","y":2025,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/128/70/","by":{"2":"21, 44"}},{"t":"case","label":"Sossamon v. Texas","cite":"563 U.S. 277","y":2011,"id":"2010/08-1438","sc":1,"sum":"The Court held that a person may not sue a state official in his individual capacity for damages under the Religious Land Use and Institutional Persons Act.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Stanley v. City of Sanford, Fla.","cite":"606 U.S. 46","y":2025,"id":"2024/23-997","sc":1,"sum":"To prevail under 42 U. S. C. §12112(a), a plaintiff must plead and prove that she held or desired a job, and could perform its essential functions with or without reasonable accommodation, at the time of an employer’s alleged act of disability-based discrimination; the judgment of the Eleventh Circuit is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"33"}},{"t":"case","label":"Tenney v. Brandhove","cite":"341 U.S. 367","y":1951,"id":"scdb/1950-081","sc":1,"sum":"From the allegations of the complaint, it appears that petitioners were acting in a field where legislators traditionally have power to act; and 8 U. S. C. §§ 43 and 47 (3) do not create civil liability for such conduct.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18","3":"11"}},{"t":"case","label":"Thompson v. United States","cite":"604 U.S. 408","y":2025,"id":"2024/23-1095","sc":1,"sum":"Title 18 U. S. C. §1014, which prohibits “knowingly mak[ing] any false statement,” does not criminalize statements that are misleading but not false.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"23, 51"}},{"t":"case","label":"Turner Broad. Sys., Inc. v. FCC","cite":"520 U.S. 180","y":1997,"id":"1996/95-992","sc":1,"sum":"In a 5-to-4 decision, the Court held that Congress \"has an independent interest in preserving a multiplicity of broadcasters.\" The outcome supported Congress's right to judge what approach would best insure a competitive communications marketplace.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Util. Air Regul. Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Xuncax v. Gramajo","cite":"886 F. Supp. 162","y":1995,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp./886/162/","by":{"2":"52"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"usc","label":"22 U.S.C. § 6084","url":"https://www.law.cornell.edu/uscode/text/22/6084","by":{"2":"8, 28"}},{"t":"law","label":"Cited Authorities Other Statutes, Pub. L. No. 95-598","url":"https://www.govinfo.gov/link/statute/92/24549","by":{"2":"22"}},{"t":"law","label":"Pub. L. No. 100-640","url":"https://www.govinfo.gov/link/statute/102/3333","by":{"2":"22"}},{"t":"law","label":"Pub. L. No. 100-669","url":"https://www.govinfo.gov/link/statute/102/3969","by":{"2":"22"}},{"t":"law","label":"Pub. L. No. 103-394","url":"https://www.govinfo.gov/link/statute/108/4106","by":{"2":"22"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"2":"23"}},{"t":"usc","label":"15 U.S.C. § 15","url":"https://www.law.cornell.edu/uscode/text/15/15","subs":["(b)"],"by":{"2":"22"}},{"t":"usc","label":"15 U.S.C. § 2688","url":"https://www.law.cornell.edu/uscode/text/15/2688","by":{"2":"51"}},{"t":"usc","label":"18 U.S.C. § 2334","url":"https://www.law.cornell.edu/uscode/text/18/2334","subs":["(e)(1)"],"by":{"2":"40"}},{"t":"usc","label":"26 U.S.C. § 6751","url":"https://www.law.cornell.edu/uscode/text/26/6751","by":{"2":"51"}},{"t":"usc","label":"29 U.S.C. § 464","url":"https://www.law.cornell.edu/uscode/text/29/464","subs":["(c)"],"by":{"2":"51"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"2":"11, 18, 19, 22"}},{"t":"usc","label":"18 U.S.C. § 1030","url":"https://www.law.cornell.edu/uscode/text/18/1030","by":{"2":"21, 22"}},{"t":"usc","label":"28 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/28/1350","by":{"2":"11, 19, 20"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)(1)"],"by":{"2":"9"}},{"t":"reg","label":"15 C.F.R. pt. 740","url":"https://www.ecfr.gov/current/title-15/part-740","by":{"2":"37"}},{"t":"reg","label":"15 C.F.R. § 740.9-21","url":"https://www.ecfr.gov/current/title-15/section-740.9-21","by":{"2":"37"}},{"t":"reg","label":"15 C.F.R. § 746.2","url":"https://www.ecfr.gov/current/title-15/section-746.2","by":{"2":"37"}},{"t":"reg","label":"31 C.F.R. pt. 515","url":"https://www.ecfr.gov/current/title-31/part-515","by":{"2":"37","3":"16"}},{"t":"reg","label":"31 C.F.R. § 515.533-591","url":"https://www.ecfr.gov/current/title-31/section-515.533-591","by":{"2":"37"}},{"t":"reg","label":"60 Fed. Reg. 54194","url":"https://www.govinfo.gov/link/fr/60/54194","by":{"2":"36"}},{"t":"case","label":"American Textile Mfrs. Inst., Inc. v. Donovan","cite":"452 U.S. 490","y":1981,"id":"1980/79-1429","sc":1,"sum":"The Court held that the language of the Occupational Safety and Health Act requires the Occupational Safety and Health Administration to engage in feasibility analysis but not a cost-benefit analysis.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Bowsher v. Merck & Co.","cite":"460 U.S. 824","y":1983,"id":"1982/81-1273","sc":1,"sum":"The Comptroller General may inspect Merck's records of direct costs but not records of indirect costs.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"Ellingburg v. United States","cite":"607 U.S. ___","y":2026,"id":"2025/24-482","sc":1,"sum":"The Court held that criminal restitution under the Mandatory Victim Restitution Act (MVRA) is penal for purposes of the Ex Post Facto Clause.","sumSrc":"Oyez","by":{"3":"24"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"3":"4, 5"}},{"t":"case","label":"F. Hoffman-La Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"sum":"The Court unanimously ruled that Congress' intent in passing the FTAIA was to prevent American courts from interfering in foreign commerce. Congress made an exception for foreign commerce that affected domestic commerce, but the exception should not be read as a general prohibition against price-fixing in all parts of the world.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"op":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"Free Enter. Fund v. PCAOB","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"3":"24"}},{"t":"case","label":"(II) H.J. Inc. v. Northwestern Bell Tel. Co.","cite":"492 U.S. 229","y":1989,"id":"1988/87-1252","sc":1,"sum":"The Racketeer Influenced and Corrupt Organizations Act (RICO), 18 U. S. C. §§ 1961-1968, which is Title IX of the Organized Crime Control Act of 1970 (OCCA), imposes criminal and civil liability upon persons who engage in certain \"prohibited activities,\" each of which is defined to include, as a necessary element, proof of a \"pattern of racketeering activity,\" § 1962. \"Racketeering activity\" means \"any act or threat …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"Hewitt v. United States","cite":"606 U.S. 419","y":2025,"id":"2024/23-1002","sc":1,"sum":"Because a sentence “has . . . been imposed” for purposes of §403(b) of the First Step Act only if the sentence is extant (i.e., has not been vacated), the Act’s more lenient penalties apply to defendants whose previous 18 U. S. C. §924(c) sentences have been vacated and who need to be resentenced following the Act’s enactment; the judgment of the Fifth Circuit is reversed and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"17"}},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"583 U.S. 202","y":2018,"id":"2017/16-534","sc":1,"sum":"The Court held that 28 U.S.C. § 1610(g) does not provide a freestanding attachment immunity exception that allows terror victim judgment creditors to attach and execute upon assets of foreign state; rather, the immunity of property must be rescinded under a separate provision under that section.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"Smith v. City of Jackson, Miss.","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"sum":"The Court held that ADEA authorized recovery in disparate-impact cases, but that in this case petitioners failed to set forth a valid claim. The Court relied on its 1971 decision in Griggs v. Duke Power, where the Court first authorized disparate-impact claims brought under Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"Townsend v. Little","cite":"109 U.S. 504","y":1883,"id":"scdb/1883-069","sc":1,"sum":"Constructive Notice — Deed—Fraud—Secret Trust — Statutes—Utah.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"16"}},{"t":"case","label":"Zedner v. United States","cite":"547 U.S. 489","y":2006,"id":"2005/05-5992","sc":1,"sum":"The Supreme Court unanimously held that a defendant may not simply waive his right to a speedy trial under the Act. The list of acceptable reasons for an \"ends-of-justice\" order by the judge includes specific mention of the defendant's need for time to obtain counsel and prepare his case.","sumSrc":"Oyez","by":{"3":"19"}}]};